import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Fraction of the remaining capacity each candidate would consume: weights / remaining."""
    r = max(float(remaining), 1.0)
    return np.clip(np.asarray(weights, dtype=float) / r, 0.0, 1.0)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Value-per-weight ratio of each candidate, scaled by the best ratio among candidates."""
    d = values / np.maximum(weights, 1)
    return d / (d.max() + 1e-9)

